INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch07$PT128-S2-Q16$batch07$, 128, 2, 16, $batch07$Agree/Disagree$batch07$, $batch07$Laurel: Modern moral theories must be jettisoned, or at least greatly reworked, because they fail to provide guidance in extreme cases, which are precisely the times when people most need guidance. Miriam: A moral theory, like an overcoat, can be quite useful even if it is not useful in every possible situation. Being useful in a wide variety of common circumstances is all we need from a moral theory.$batch07$, $batch07$Laurel's and Miriam's statements provide the most support for the claim that they disagree about whether$batch07$, $batch07$C$batch07$, true, $batch07$Batch 07; question text from local bank.$batch07$ FROM lr_sections s WHERE s.preptest=128 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch07$PT128-S2-Q16$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$A$batch07$, $batch07$it is preferable to develop a moral theory that provides solutions to all the moral dilemmas that could arise$batch07$, $batch07$Half Scope$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT128-S2-Q16$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$A$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$B$batch07$, $batch07$people abandoned earlier moral theories when they encountered dilemmas that those theories did not adequately address$batch07$, $batch07$Out of Scope$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT128-S2-Q16$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$B$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$C$batch07$, $batch07$a moral theory's adequacy depends on its ability to provide guidance in extreme cases$batch07$, $batch07$Correct$batch07$, true FROM lr_questions q WHERE q.qid=$batch07$PT128-S2-Q16$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$C$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$D$batch07$, $batch07$just as people need different overcoats in different climates, so too do they need different moral theories on different occasions$batch07$, $batch07$Out of Scope$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT128-S2-Q16$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$D$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$E$batch07$, $batch07$a moral theory developed in the light of extreme cases is unlikely to provide adequate guidance in more usual cases$batch07$, $batch07$Out of Scope$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT128-S2-Q16$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$E$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT128-S2-Q16$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Laurel's Position$batch07$, $batch07$Modern moral theories must be discarded or greatly reworked, because they fail to guide us in extreme cases, when we need guidance most.$batch07$), (1, $batch07$Miriam's Position$batch07$, $batch07$A moral theory, like an overcoat, can be useful without working in every situation. Working well in common circumstances is all we need.$batch07$), (2, $batch07$Evaluate$batch07$, $batch07$Laurel treats failure in extreme cases as fatal. Miriam says a theory only needs to handle common cases. So they disagree about the standard a moral theory has to meet: does it have to work in the extreme cases?$batch07$), (3, $batch07$Goal$batch07$, $batch07$Whether a moral theory is inadequate if it fails in extreme cases.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT128-S2-Q16$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$Laurel wants guidance in extreme cases, not answers to every possible dilemma. And Miriam never says a complete theory wouldn't be *preferable*. Miriam says we don't *need* one. "Preferable" and "needed" are different claims.$batch07$), ($batch07$B$batch07$, $batch07$Neither speaker talks about what people did with earlier moral theories.$batch07$), ($batch07$C$batch07$, $batch07$Laurel: theories that fail in extreme cases must go. Miriam: being useful in "a wide variety of common circumstances is all we need".$batch07$), ($batch07$D$batch07$, $batch07$This twists the analogy. Miriam's overcoat point is that one coat can be useful even if it doesn't suit every situation, not that we need different theories for different occasions.$batch07$), ($batch07$E$batch07$, $batch07$Nobody talks about theories built around extreme cases, or how they do in usual cases.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT128-S2-Q16$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
